INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m27171$nota-0122$m27171$, $m27172$Training and Racing with a Power Meter.pdf$m27172$, $m27173$361$m27173$, $m27174$Now let's compare the same two power files using Quadrant Analysis and see if the athlete is training in the correct quadrants to specifically address the neuromuscular system... the majority of his time pedaling fell into Quadrants III and IV... this training ride accomplished the goal of stressing his metabolic fitness, [but] it did not place much emphasis on the use of his Type II, or fast-twitch, muscle fibers.$m27174$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m27175$nota-0122$m27175$, $m27176$Training and Racing with a Power Meter.pdf$m27176$, $m27177$363$m27177$, $m27178$It is apparent that the race put a much larger demand on multiple neuromuscular capabilities than the training ride did... although the majority of the ride was in Quadrant III, it also contained quite a lot of effort in Quadrant II.$m27178$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m27179$nota-0122$m27179$, $m27180$nota-0067$m27180$, $m27181$pre-requisito$m27181$, $m27182$aplica o conceito de Quadrant Analysis (nota-0067) para comparar treino contra a demanda real da prova-alvo$m27182$)
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m27183$nota-0122$m27183$, $m27184$nota-0110$m27184$, $m27185$complementa$m27185$, $m27186$generaliza para qualquer modalidade (aqui, MTB/estrada) o mesmo princípio de checagem de especificidade já aplicado ao triathlon na nota-0110$m27186$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m27187$nota-0124$m27187$, $m27188$Training and Racing with a Power Meter.pdf$m27188$, $m27189$364$m27189$, $m27190$You can pinpoint the areas in which you could improve your fatigue resistance... by reviewing your Power Duration Curve and comparing it to your best power when you're fresh versus after a certain amount of work has been done. You may be able to knock out 300 watts for 20 minutes when you are fresh, but what can you do after you have completed 2,000 kJs of work?$m27190$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m27191$nota-0124$m27191$, $m27192$Training and Racing with a Power Meter.pdf$m27192$, $m27193$365$m27193$, $m27194$Bill Masters's fatigue resistance chart shows a dramatic difference between his best 5-minute and 20-minute power when he is fresh at the beginning of a ride as compared to after 2,000 kJs of work. His 5-minute power drops from 261 watts to 202 watts, and his 20-minute power drops from 241 watts to 187 watts.$m27194$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m27195$nota-0124$m27195$, $m27196$Training and Racing with a Power Meter.pdf$m27196$, $m27197$366$m27197$, $m27198$he clearly has a very high fatigue resistance for a longer, 15-second sprint, which starts at 1,274 watts and drops only 20 percent after 15 seconds. Extend it out to a 41 percent degradation at 35 seconds into his sprint... he's still producing over 800 watts!$m27198$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m27199$nota-0124$m27199$, $m27200$nota-0079$m27200$, $m27201$complementa$m27201$, $m27202$método alternativo/complementar ao conceito de Stamina (nota-0079) para quantificar degradação de potência com o acúmulo de trabalho$m27202$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m27203$nota-0125$m27203$, $m27204$Training and Racing with a Power Meter.pdf$m27204$, $m27205$371$m27205$, $m27206$you could just as easily use the quasi-plateau in power that occurs after the 1.5- to 2.5-minute mark of a well-paced pursuit... this is essentially the rider's power at VO2max, as would be expected, since anaerobic capacity (as measured by maximal accumulated oxygen deficit) is generally completely used up after that period of time. So from that point, further exercise can only be performed on a 'pay as you go' basis (i.e., 100 percent aerobically).$m27206$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m27207$nota-0125$m27207$, $m27208$nota-0082$m27208$, $m27209$complementa$m27209$, $m27210$oferece um método de campo (sem laboratório) para estimar a potência de VO2max, complementando os métodos de Power Profile/PDC/Mapa Fenotípico (nota-0082, Cap.8) e o teste 5min+20min (nota-0101)$m27210$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m27211$nota-0128$m27211$, $m27212$Training and Racing with a Power Meter.pdf$m27212$, $m27213$367$m27213$, $m27214$approximately 85 percent of a pursuiter's power output is used to overcome wind resistance... (The other sources of resistance—inertia, rolling resistance, and drivetrain and bearing friction—account for approximately 8 percent, 5 percent, and 2 percent, respectively.)$m27214$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m27215$nota-0130$m27215$, $m27216$Training and Racing with a Power Meter.pdf$m27216$, $m27217$378$m27217$, $m27218$Power-meter files from cyclocross races typically show an average of 20 to 40 watts below the actual FTP of the athlete. One reason for this is that there is so much downtime, spent coasting down a technical hill or running with the bike. The other reason is that many of the courses lack good traction...$m27218$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m27219$nota-0130$m27219$, $m27220$Training and Racing with a Power Meter.pdf$m27220$, $m27221$379$m27221$, $m27222$One thing that is important to identify in a cyclocross power file is the number of watts above FTP and the length of each of these efforts... A cyclocross match is a little different from a match in a road race or a criterium, however, because most likely the racer is already at his or her FTP when the need to do a hard effort arises. In this case, the matches are more like bursts of flames coming up from an already raging fire!$m27222$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m27223$nota-0130$m27223$, $m27224$nota-0065$m27224$, $m27225$complementa$m27225$, $m27226$redefine o conceito de 'matches' (esforços acima da FTP, já registrado nas notas do Cap.7) para o contexto específico do ciclocross, onde a base já está perto da FTP$m27226$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m27227$nota-0132$m27227$, $m27228$Training and Racing with a Power Meter.pdf$m27228$, $m27229$382$m27229$, $m27230$even on an indoor track, the environmental conditions... most races on the track are too short for Normalized Power data to be readily interpretable.$m27230$);
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m27231$nota-0132$m27231$, $m27232$Training and Racing with a Power Meter.pdf$m27232$, $m27233$384$m27233$, $m27234$The general concepts behind Training Stress Score, however, remain valid, and the Performance Manager approach can still be effectively used to monitor a rider's overall training load... However, care must be taken when analyzing track workouts to delete any significant portions of the file where the rider was not actively pedaling; otherwise the TSS score may be artificially inflated.$m27234$);
INSERT INTO notas_relacoes (nota_origem_id, nota_destino_id, tipo, justificativa) VALUES ($m27235$nota-0132$m27235$, $m27236$nota-0059$m27236$, $m27237$pre-requisito$m27237$, $m27238$limitação de aplicabilidade da NP (nota-0059) em esforços muito curtos e não-pedalados típicos de provas de pista$m27238$)
INSERT INTO notas_fontes (nota_id, arquivo, pagina, trecho) VALUES ($m27239$nota-0135$m27239$, $m27240$Training and Racing with a Power Meter.pdf$m27240$, $m27241$388$m27241$, $m27242$Jeff and his colleagues measured the power that team pursuit riders produced in various positions in the paceline as well as their power during exchanges. They observed that riders in the second, third, or fourth position required only 64–71 percent of the power required for the lead rider.$m27242$);
